document.addEventListener("DOMContentLoaded", () => {

    // ── Inputs ────────────────────────────────────────────────────────
    const inpColor  = document.getElementById("inp-color");
    const inpFont   = document.getElementById("inp-font");
    const inpUni    = document.getElementById("inp-uni");
    const inpTopic  = document.getElementById("inp-topic");
    const inpCourseTitle = document.getElementById("inp-course-title");
    const inpCourseCode  = document.getElementById("inp-course-code");
    const inpStudentName = document.getElementById("inp-student-name");
    const inpStudentId   = document.getElementById("inp-student-id");
    const inpDept        = document.getElementById("inp-dept");
    const inpSemester    = document.getElementById("inp-semester");
    const inpSection     = document.getElementById("inp-section");
    const inpTeacherName = document.getElementById("inp-teacher-name");
    const inpTeacherDesig= document.getElementById("inp-teacher-desig");
    const inpDate        = document.getElementById("inp-date");
    const inpLogo        = document.getElementById("inp-logo");

    const preview   = document.getElementById("a4-preview");
    const btnModeAll = document.getElementById("btn-mode-all");
    const btnModeSeu = document.getElementById("btn-mode-seu");
    const landingSelection = document.getElementById("landing-selection");
    const generatorInterface = document.getElementById("generator-interface");
    const cardSelectAll = document.getElementById("card-select-all");
    const cardSelectSeu = document.getElementById("card-select-seu");
    const btnBackSelection = document.getElementById("btn-back-selection");

    let currentTemplate = "royal";
    let currentMode = "all"; // 'all' or 'seu'

    const defaultLogo = "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'%3E%3Ccircle cx='50' cy='50' r='45' fill='%23e5e7eb'/%3E%3Ctext x='50' y='58' font-size='18' text-anchor='middle' fill='%236b7280' font-family='sans-serif'%3ELOGO%3C/text%3E%3C/svg%3E";

    // Official uploaded logo image for Southeast University (Candle & Book logo)
    const seuLogo = "data:image/png;base64,";

    let customLogoSrc = null;
    let logoSrc = defaultLogo;

    // Landing cards → navigate to separate URL pages (handled by <a href> in HTML)
    // Back button → go back to landing
    if (btnBackSelection) {
        btnBackSelection.addEventListener("click", () => {
            window.location.href = "assignment-cover.html";
        });
    }

    // Mode Switcher logic
    if (btnModeAll && btnModeSeu) {
        btnModeAll.addEventListener("click", () => {
            currentMode = "all";
            btnModeAll.classList.add("active");
            btnModeAll.style.background = "var(--primary)";
            btnModeAll.style.color = "#fff";
            btnModeAll.style.borderColor = "var(--primary)";
            btnModeSeu.classList.remove("active");
            btnModeSeu.style.background = "var(--bg-primary)";
            btnModeSeu.style.color = "var(--text-primary)";
            btnModeSeu.style.borderColor = "var(--border-color)";

            inpUni.value = "";
            inpUni.readOnly = false;
            inpUni.placeholder = "";
            logoSrc = customLogoSrc || defaultLogo;
            render();
        });

        btnModeSeu.addEventListener("click", () => {
            currentMode = "seu";
            btnModeSeu.classList.add("active");
            btnModeSeu.style.background = "var(--primary)";
            btnModeSeu.style.color = "#fff";
            btnModeSeu.style.borderColor = "var(--primary)";
            btnModeAll.classList.remove("active");
            btnModeAll.style.background = "var(--bg-primary)";
            btnModeAll.style.color = "var(--text-primary)";
            btnModeAll.style.borderColor = "var(--border-color)";

            inpUni.value = "Southeast University";
            inpUni.readOnly = true;
            logoSrc = seuLogo;
            inpColor.value = "#003366";
            render();
        });

    } // end if (btnModeAll && btnModeSeu)


    // ── Template Renderers ───────────────────────────────────────────


    function getData() {
        return {
            uni:         inpUni.value.trim(),
            topic:       inpTopic.value.trim(),
            courseTitle: inpCourseTitle.value.trim(),
            courseCode:  inpCourseCode.value.trim(),
            studentName: inpStudentName.value.trim(),
            studentId:   inpStudentId.value.trim(),
            dept:        inpDept.value.trim(),
            semester:    inpSemester.value.trim(),
            section:     inpSection.value.trim(),
            teacherName: inpTeacherName.value.trim(),
            teacherDesig:inpTeacherDesig.value.trim(),
            date:        inpDate.value.trim(),
        };
    }

    function field(label, value, cls) {
        // Label always shows, value shows only when filled
        return `<div class="${cls}"><strong>${label}</strong> <span>: ${value || ''}</span></div>`;
    }

    function submittedByFields(d, fieldClass) {
        return [
            field('Name',     d.studentName, fieldClass),
            field('ID',       d.studentId,   fieldClass),
            field('Dept.',    d.dept,        fieldClass),
            field('Semester', d.semester,    fieldClass),
            field('Section',  d.section,     fieldClass),
        ].join('');
    }

    function submittedToFields(d, fieldClass) {
        return [
            field('Name',        d.teacherName,  fieldClass),
            field('Designation', d.teacherDesig, fieldClass),
        ].join('');
    }

    const templates = {

        // 1. Royal Academic
        royal: (d) => `
            <div class="t-outer-ring"></div>
            <div class="t-inner-ring"></div>
            <div class="t-corner tl"></div><div class="t-corner tr"></div>
            <div class="t-corner bl"></div><div class="t-corner br"></div>
            <div class="t-body">
                <img class="t-logo" src="${logoSrc}" alt="Logo">
                ${d.uni ? '<div class="t-uni">' + d.uni + '</div>' : ''}
                <div class="t-divider"><hr><span>✦</span><hr></div>
                <div class="t-badge">ASSIGNMENT</div>
                ${d.topic ? '<div class="t-topic">' + d.topic + '</div>' : ''}
                ${d.courseTitle ? '<div class="t-course-row"><strong>Course Title:</strong> ' + d.courseTitle + '</div>' : ''}
                ${d.courseCode  ? '<div class="t-course-row"><strong>Course Code:</strong> ' + d.courseCode + '</div>' : ''}
                <hr class="t-hr">
                <div class="t-info-row">
                    <div>
                        <div class="t-col-label">Submitted By</div>
                        ${submittedByFields(d, 't-field')}
                    </div>
                    <div>
                        <div class="t-col-label">Submitted To</div>
                        ${submittedToFields(d, 't-field')}
                    </div>
                </div>
                <div class="t-date-strip">Date of Submission: ${d.date}</div>
            </div>
        `,

        // 2. Bold Banner
        banner: (d) => `
            <div class="t-sidebar">
                <span class="t-sidebar-text">${d.uni || 'ASSIGNMENT'}</span>
            </div>
            <div class="t-main">
                <div class="t-header">
                    <img class="t-logo" src="${logoSrc}" alt="Logo">
                    ${d.uni ? '<div class="t-uni">' + d.uni + '</div>' : ''}
                </div>
                <div class="t-content">
                    <div class="t-badge">ASSIGNMENT</div>
                    ${d.topic ? '<div class="t-topic-label">Topic</div><div class="t-topic">' + d.topic + '</div>' : ''}
                    ${d.courseTitle ? '<div class="t-meta-row"><strong>Course Title:</strong> ' + d.courseTitle + '</div>' : ''}
                    ${d.courseCode  ? '<div class="t-meta-row"><strong>Course Code:</strong> ' + d.courseCode + '</div>' : ''}
                    <hr class="t-divider">
                    <div class="t-info-row">
                        <div>
                            <div class="t-col-label">Submitted By</div>
                            ${submittedByFields(d, 't-field')}
                        </div>
                        <div>
                            <div class="t-col-label">Submitted To</div>
                            ${submittedToFields(d, 't-field')}
                        </div>
                    </div>
                    <div class="t-date">📅 Date of Submission: ${d.date}</div>
                </div>
            </div>
        `,

        // 3. Split Dark
        split: (d) => `
            <div class="t-top-half">
                <div class="t-top-circle"></div>
                <div class="t-top-circle2"></div>
                <img class="t-logo" src="${logoSrc}" alt="Logo">
                ${d.uni ? '<div class="t-uni">' + d.uni + '</div>' : ''}
                <div class="t-badge">ASSIGNMENT</div>
            </div>
            <div class="t-bottom">
                ${d.topic ? '<div class="t-topic">"' + d.topic + '"</div>' : ''}
                ${d.courseTitle ? '<div class="t-course-row"><strong>Course Title:</strong> ' + d.courseTitle + '</div>' : ''}
                ${d.courseCode  ? '<div class="t-course-row"><strong>Course Code:</strong> ' + d.courseCode + '</div>' : ''}
                <hr class="t-hr">
                <div class="t-info-row">
                    <div>
                        <div class="t-col-label">Submitted By</div>
                        ${submittedByFields(d, 't-field')}
                    </div>
                    <div>
                        <div class="t-col-label">Submitted To</div>
                        ${submittedToFields(d, 't-field')}
                    </div>
                </div>
                <div class="t-date">Date of Submission: ${d.date}</div>
            </div>
        `,

        // 4. Elegant Border
        elegant: (d) => `
            <div class="t-frame"></div>
            <div class="t-frame-inner"></div>
            <div class="t-orn tl"></div><div class="t-orn tr"></div>
            <div class="t-orn bl"></div><div class="t-orn br"></div>
            <div class="t-body">
                <img class="t-logo" src="${logoSrc}" alt="Logo">
                ${d.uni  ? '<div class="t-uni">' + d.uni + '</div>' : ''}
                ${d.dept ? '<div class="t-dept">' + d.dept + ' Department</div>' : ''}
                <div class="t-badge">ASSIGNMENT</div>
                ${d.topic ? '<div class="t-topic">' + d.topic + '</div>' : ''}
                ${(d.courseTitle || d.courseCode) ? '<div class="t-course-row"><strong>Course:</strong> ' + (d.courseTitle || '') + (d.courseTitle && d.courseCode ? ' (' + d.courseCode + ')' : d.courseCode) + '</div>' : ''}
                <div class="t-ornament-line"><hr><span>❧</span><hr></div>
                <div class="t-info-row">
                    <div>
                        <div class="t-col-label">Submitted By</div>
                        ${submittedByFields(d, 't-field')}
                    </div>
                    <div>
                        <div class="t-col-label">Submitted To</div>
                        ${submittedToFields(d, 't-field')}
                    </div>
                </div>
                <div class="t-date">Date of Submission: ${d.date}</div>
            </div>
        `,

        // 5. Modern Card
        card: (d) => `
            <div class="t-top-accent"></div>
            <div class="t-header-card">
                <img class="t-logo" src="${logoSrc}" alt="Logo">
                ${d.uni ? '<div class="t-uni">' + d.uni + '</div>' : ''}
            </div>
            <div class="t-badge-wrap"><div class="t-badge">ASSIGNMENT</div></div>
            <div class="t-topic-card">
                <div class="t-topic-label">Topic</div>
                ${d.topic ? '<div class="t-topic">' + d.topic + '</div>' : ''}
                ${(d.courseTitle || d.courseCode) ? '<div class="t-course-row"><strong>Course:</strong> ' + (d.courseTitle || '') + (d.courseTitle && d.courseCode ? ' &nbsp;|&nbsp; <strong>Code:</strong> ' + d.courseCode : d.courseCode) + '</div>' : ''}
            </div>
            <div class="t-info-row">
                <div class="t-info-card">
                    <div class="t-col-label">Submitted By</div>
                    ${submittedByFields(d, 't-field')}
                </div>
                <div class="t-info-card">
                    <div class="t-col-label">Submitted To</div>
                    ${submittedToFields(d, 't-field')}
                </div>
            </div>
            <div class="t-date">📅 Date of Submission: ${d.date}</div>
        `,

        // 6. Clean Minimal
        minimal: (d) => `
            <div class="t-header">
                <img class="t-logo" src="${logoSrc}" alt="Logo">
                <div>
                    ${d.uni ? '<div class="t-uni">' + d.uni + '</div>' : ''}
                    ${d.dept ? '<div class="t-dept">' + d.dept + ' Department</div>' : ''}
                </div>
            </div>
            <div class="t-badge">ASSIGNMENT</div>
            <div class="t-topic-box">
                <div class="t-topic-label">Assignment Topic</div>
                ${d.topic ? '<div class="t-topic">' + d.topic + '</div>' : ''}
                ${d.courseTitle ? '<div class="t-meta-item"><strong>Course Title:</strong> ' + d.courseTitle + '</div>' : ''}
                ${d.courseCode  ? '<div class="t-meta-item"><strong>Course Code:</strong> ' + d.courseCode + '</div>' : ''}
            </div>
            <div class="t-info-row">
                <div class="t-info-box">
                    <div class="t-col-label">Submitted By</div>
                    ${submittedByFields(d, 't-field')}
                </div>
                <div class="t-info-box">
                    <div class="t-col-label">Submitted To</div>
                    ${submittedToFields(d, 't-field')}
                </div>
            </div>
            <div class="t-date">📅 Date of Submission: ${d.date}</div>
        `,

        // 7. Tech Geometric
        geometric: (d) => `
            <div class="t-geo-header">
                <img class="t-logo" src="${logoSrc}" alt="Logo">
                ${d.uni ? '<div class="t-uni">' + d.uni + '</div>' : ''}
            </div>
            <div class="t-body">
                <div class="t-badge-row">
                    <div class="t-badge">ASSIGNMENT</div>
                </div>
                <div class="t-topic-block">
                    ${d.topic ? '<div class="t-topic">' + d.topic + '</div>' : ''}
                    ${d.courseTitle ? '<div class="t-course-row"><strong>Course:</strong> ' + d.courseTitle + (d.courseCode ? ' (' + d.courseCode + ')' : '') + '</div>' : ''}
                </div>
                <div class="t-info-row">
                    <div class="t-info-card">
                        <div class="t-col-label">Submitted By</div>
                        ${submittedByFields(d, 't-field')}
                    </div>
                    <div class="t-info-card">
                        <div class="t-col-label">Submitted To</div>
                        ${submittedToFields(d, 't-field')}
                    </div>
                </div>
            </div>
            <div class="t-geo-footer">
                Date of Submission: ${d.date}
            </div>
        `,

        // 8. Corporate Pro
        corporate: (d) => `
            <div class="t-header">
                <div class="t-header-text">
                    ${d.uni ? '<div class="t-uni">' + d.uni + '</div>' : ''}
                    ${d.dept ? '<div class="t-dept">' + d.dept + '</div>' : ''}
                </div>
                <img class="t-logo" src="${logoSrc}" alt="Logo">
            </div>
            <div class="t-body">
                <div class="t-badge-strip">
                    <div class="t-badge">ASSIGNMENT REPORT</div>
                </div>
                <div class="t-topic-wrap">
                    <div class="t-topic-label">Subject & Topic</div>
                    ${d.topic ? '<div class="t-topic">' + d.topic + '</div>' : ''}
                    ${d.courseTitle ? '<div class="t-course-row"><strong>Course Title:</strong> ' + d.courseTitle + '</div>' : ''}
                    ${d.courseCode  ? '<div class="t-course-row"><strong>Course Code:</strong> ' + d.courseCode + '</div>' : ''}
                </div>
                <div class="t-info-table">
                    <div class="t-table-card">
                        <div class="t-col-label">Submitted By</div>
                        <div class="t-table-body">
                            ${submittedByFields(d, 't-field')}
                        </div>
                    </div>
                    <div class="t-table-card">
                        <div class="t-col-label">Submitted To</div>
                        <div class="t-table-body">
                            ${submittedToFields(d, 't-field')}
                        </div>
                    </div>
                </div>
                <div class="t-date">
                    <span>Submission Date:</span>
                    <span>${d.date}</span>
                </div>
            </div>
        `,

        // 9. Ivy Classic
        crest: (d) => `
            <div class="t-crest-border"></div>
            <div class="t-crest-border-inner"></div>
            <img class="t-logo" src="${logoSrc}" alt="Logo">
            ${d.uni ? '<div class="t-uni">' + d.uni + '</div>' : ''}
            <div class="t-laurel">✦ ❖ ✦</div>
            <div class="t-badge">ASSIGNMENT</div>
            ${d.topic ? '<div class="t-topic">"' + d.topic + '"</div>' : ''}
            ${d.courseTitle ? '<div class="t-course-row"><strong>Course Title:</strong> ' + d.courseTitle + '</div>' : ''}
            ${d.courseCode  ? '<div class="t-course-row"><strong>Course Code:</strong> ' + d.courseCode + '</div>' : ''}
            <div class="t-divider-diamond">♦ ♦ ♦</div>
            <div class="t-info-row">
                <div>
                    <div class="t-col-label">Submitted By</div>
                    ${submittedByFields(d, 't-field')}
                </div>
                <div>
                    <div class="t-col-label">Submitted To</div>
                    ${submittedToFields(d, 't-field')}
                </div>
            </div>
            <div class="t-date">Date of Submission: ${d.date}</div>
        `,

        // 10. Modern Wave
        wave: (d) => `
            <div class="t-wave-header">
                <div class="t-logo-circle">
                    <img class="t-logo" src="${logoSrc}" alt="Logo">
                </div>
                ${d.uni ? '<div class="t-uni">' + d.uni + '</div>' : ''}
            </div>
            <div class="t-body">
                <div class="t-badge-wrap">
                    <div class="t-badge">ASSIGNMENT</div>
                </div>
                <div class="t-topic-card">
                    <div class="t-topic-label">Assignment Topic</div>
                    ${d.topic ? '<div class="t-topic">' + d.topic + '</div>' : ''}
                    ${(d.courseTitle || d.courseCode) ? '<div class="t-course-row"><strong>Course:</strong> ' + (d.courseTitle || '') + (d.courseTitle && d.courseCode ? ' (' + d.courseCode + ')' : d.courseCode) + '</div>' : ''}
                </div>
                <div class="t-info-row">
                    <div class="t-info-card">
                        <div class="t-col-label">Submitted By</div>
                        ${submittedByFields(d, 't-field')}
                    </div>
                    <div class="t-info-card">
                        <div class="t-col-label">Submitted To</div>
                        ${submittedToFields(d, 't-field')}
                    </div>
                </div>
                <div class="t-date">Date of Submission: ${d.date}</div>
            </div>
        `,
    };

    // ── Render ────────────────────────────────────────────────────────
    function render() {
        const d = getData();
        const color = inpColor.value;
        const font  = inpFont.value;

        // Set class
        preview.className = `tpl-${currentTemplate}`;
        // Set CSS variable for theme color
        preview.style.setProperty("--t", color);
        preview.style.fontFamily = font;

        // Render HTML
        preview.innerHTML = templates[currentTemplate](d);
    }

    // ── Template Buttons ──────────────────────────────────────────────
    document.querySelectorAll(".tpl-btn").forEach(btn => {
        btn.addEventListener("click", () => {
            document.querySelectorAll(".tpl-btn").forEach(b => b.classList.remove("active"));
            btn.classList.add("active");
            currentTemplate = btn.dataset.tpl;
            render();
        });
    });

    // ── Live bindings ─────────────────────────────────────────────────
    [inpUni, inpTopic, inpCourseTitle, inpCourseCode,
     inpStudentName, inpStudentId, inpDept, inpSemester,
     inpSection, inpTeacherName, inpTeacherDesig, inpDate
    ].forEach(el => el.addEventListener("input", render));

    inpColor.addEventListener("input", render);
    inpFont.addEventListener("change", render);

    // ── Logo Upload ───────────────────────────────────────────────────
    inpLogo.addEventListener("change", (e) => {
        const file = e.target.files[0];
        if (file) {
            const reader = new FileReader();
            reader.onload = (event) => {
                customLogoSrc = event.target.result;
                logoSrc = customLogoSrc;
                render();
            };
            reader.readAsDataURL(file);
        }
    });

    // ── Preview Scaling ───────────────────────────────────────────────
    const previewContainer = document.querySelector('.preview-container');
    const resizePreview = () => {
        if (!previewContainer || !preview) return;
        const padding = window.innerWidth <= 576 ? 10 : 40;
        const containerWidth = previewContainer.clientWidth - padding;
        const paperWidth = 794;
        if (containerWidth > 0 && containerWidth < paperWidth) {
            const scale = containerWidth / paperWidth;
            preview.style.transform = `scale(${scale})`;
            previewContainer.style.height = `${(1123 * scale) + padding}px`;
        } else {
            preview.style.transform = 'scale(1)';
            previewContainer.style.height = `${1123 + padding}px`;
        }
    };
    window.addEventListener('resize', resizePreview);
    window.addEventListener('orientationchange', () => setTimeout(resizePreview, 200));
    setTimeout(resizePreview, 150);

    // ── Download ──────────────────────────────────────────────────────
    const generateCanvas = async () => {
        const originalTransform = preview.style.transform;
        preview.style.transform = 'scale(1)';
        await new Promise(r => setTimeout(r, 80));
        const canvas = await html2canvas(preview, {
            scale: 2, useCORS: true, backgroundColor: "#ffffff", logging: false
        });
        preview.style.transform = originalTransform;
        return canvas;
    };

    document.getElementById("btn-dl-png").addEventListener("click", async () => {
        const btn = document.getElementById("btn-dl-png");
        btn.textContent = "⏳ Generating...";
        const canvas = await generateCanvas();
        const link = document.createElement("a");
        link.download = "assignment-cover.png";
        link.href = canvas.toDataURL("image/png");
        link.click();
        btn.textContent = "🖼️ Download PNG";
    });

    document.getElementById("btn-dl-pdf").addEventListener("click", async () => {
        const btn = document.getElementById("btn-dl-pdf");
        btn.textContent = "⏳ Generating...";
        const canvas = await generateCanvas();
        const { jsPDF } = window.jspdf;
        const pdf = new jsPDF({ orientation: "portrait", unit: "mm", format: "a4" });
        const imgData = canvas.toDataURL("image/jpeg", 1.0);
        pdf.addImage(imgData, "JPEG", 0, 0, 210, 297);
        pdf.save("assignment-cover.pdf");
        btn.textContent = "⬇️ Download PDF (A4)";
    });

    // ── Initial Render & Page Mode Setup ──────────────────────────────
    // Must be here (after all const/function definitions) so templates, render, resizePreview are all available
    const urlParams = new URLSearchParams(window.location.search);
    const urlMode = urlParams.get("mode"); // 'all', 'seu', or null

    if (urlMode === "seu" || urlMode === "all") {
        // Show generator, hide landing
        if (landingSelection) landingSelection.style.display = "none";
        if (generatorInterface) generatorInterface.style.display = "grid";

        const toolTitleEl = document.querySelector(".tool-title");
        if (urlMode === "seu") {
            inpUni.value = "Southeast University";
            inpUni.readOnly = true;
            logoSrc = seuLogo;
            if (inpColor) inpColor.value = "#003366";
            if (toolTitleEl) toolTitleEl.textContent = "📄 Assignment Cover Generator (SEU)";
            document.title = "Assignment Cover Generator (SEU) - ToolX Pro";
        } else {
            inpUni.value = "";
            inpUni.readOnly = false;
            inpUni.placeholder = "e.g. University of Dhaka";
            logoSrc = defaultLogo;
            if (toolTitleEl) toolTitleEl.textContent = "📄 Assignment Cover Generator (All Universities)";
            document.title = "Assignment Cover Generator (All Universities) - ToolX Pro";
        }
        render();
        setTimeout(resizePreview, 150);
    } else {
        // No mode param → show landing, hide generator
        if (landingSelection) landingSelection.style.display = "block";
        if (generatorInterface) generatorInterface.style.display = "none";
        const toolTitleEl = document.querySelector(".tool-title");
        if (toolTitleEl) toolTitleEl.textContent = "📄 Assignment Cover Generator";
    }

});
